//! Exact word-set summary for the unchanged native-process CAM observer.
//! MPAS module_ra_cam.F:678-679; this diagnoses, never grants an exclusion.
use std::{env,fs,path::Path,collections::BTreeMap};
fn main(){let args:Vec<_>=env::args().collect();let root=Path::new(&args[1]);let mut paths:Vec<_>=fs::read_dir(root).unwrap().map(|x|x.unwrap().path()).filter(|p|p.extension().and_then(|x|x.to_str())==Some("raw")).collect();paths.sort();let mut first=BTreeMap::new();let mut comma=false;println!("{{\"scope\":\"exact native-process boundary words; no exclusion or cross-host qualification\",\"arrays\":[");for path in paths {let name=path.file_stem().unwrap().to_str().unwrap();let fields:Vec<_>=name.split('-').collect();assert_eq!(fields.len(),3);let data=fs::read(&path).unwrap();assert_eq!(data.len()%4,0);let key=(fields[0].to_string(),fields[2].to_string());let baseline=first.entry(key).or_insert_with(||fs::read(root.join(format!("{}-call1-{}.raw",fields[0],fields[2]))).unwrap());assert_eq!(baseline.len(),data.len());let differences=data.chunks_exact(4).zip(baseline.chunks_exact(4)).filter(|(a,b)|a!=b).count();let mut values=BTreeMap::<u32,usize>::new();let mut ranges=Vec::new();let mut start=None;for (index,word) in data.chunks_exact(4).map(|w|u32::from_le_bytes(w.try_into().unwrap())).enumerate(){*values.entry(word).or_default()+=1;if word!=0 && start.is_none(){start=Some(index);}if word==0 {if let Some(lo)=start.take(){ranges.push((lo,index));}}}if let Some(lo)=start {ranges.push((lo,data.len()/4));}if comma{println!(",");}comma=true;print!("{{\"file\":\"{}\",\"words\":{},\"differing_words_from_call1\":{},\"nonzero_ranges\":[",path.file_name().unwrap().to_str().unwrap(),data.len()/4,differences);for (i,(lo,hi)) in ranges.iter().enumerate(){if i>0{print!(",");}print!("[{},{}]",lo,hi);}print!("],\"word_values\":{{");let mut sep=false;for (value,count) in values {if sep {print!(",");}sep=true;print!("\"{:08x}\":{}",value,count);}print!("}}}}");}println!("]}}");}
